<script setup lang="ts">import{useAppStore}from'../stores/app';import EmmaPortrait from'../components/EmmaPortrait.vue';import StatBar from'../components/StatBar.vue';import{MapPin,GraduationCap,Camera,LockKeyhole}from'@lucide/vue';const store=useAppStore()</script>
<template><section class="profile"><div class="profile-hero"><div class="profile-top"><small>HER PROFILE</small><b>♡ {{store.relationship}}</b></div><EmmaPortrait expression="smile" :src="store.activeCharacter.image" full/><div class="profile-name"><p>{{store.activeCharacter.englishName}}</p><h1>{{store.activeCharacter.name}} <span>{{store.activeCharacter.age}}</span></h1></div></div><div class="profile-body"><div class="card"><div class="info"><MapPin/><span><small>FROM</small>{{store.activeCharacter.origin}}</span></div><div class="info"><GraduationCap/><span><small>MAJOR</small>{{store.activeCharacter.major}}</span></div><div class="info"><Camera/><span><small>HOBBIES</small>{{store.activeCharacter.hobbies.join('・')}}</span></div></div><div class="card relationship"><div class="section-title"><h3>ふたりの関係</h3><span>{{store.relationship}}</span></div><StatBar label="Affection - 愛情" :value="store.progress.affection" icon="♥"/><StatBar label="Trust - 信頼" :value="store.progress.trust" icon="✦" color="#8b82dc"/></div><div class="card bio"><h3>About {{store.activeCharacter.englishName.split(' ')[0]}}</h3><p>{{store.activeCharacter.description}} 距離が縮まると冗談や本音が増えていく。</p><div :class="{secret:store.progress.completed.length<2}"><LockKeyhole v-if="store.progress.completed.length<2"/><span><small>FAVORITE FOOD</small>{{store.progress.completed.length>=2?'スパイシーカレー':'もっと仲良くなると解放'}}</span></div><div :class="{secret:store.progress.completed.length<3}"><LockKeyhole v-if="store.progress.completed.length<3"/><span><small>HER DREAM</small>{{store.progress.completed.length>=3?'世界をつなぐ仕事をすること':'特別な思い出で解放'}}</span></div></div></div></section></template>
